# ==============================================================================\n#  GARMIN -> DRIVE SYNC (FINAL CLEAN VERSION)\n# ==============================================================================\n#  1. AUTHENTICATION: Logs in using your 3-part secret.\n#  2. DATA DIET: Removes all long arrays (Movement, SpO2, Respiration).\n#  3. TIMEZONE: Forces CST (UTC-6) for accurate daily tracking.\n#  4. FILENAME: Saves as "health_YYYY-MM-DD_HH-MM-SS.json"\n# ==============================================================================\n\nimport json\nimport os\nimport sys\nimport base64\nimport io\nimport re\nimport traceback\nimport urllib.parse\nfrom datetime import datetime, timezone, timedelta\n\n# --- Third-Party Libraries ---\nfrom garminconnect import Garmin\nimport garth\nfrom google.oauth2.credentials import Credentials\nfrom googleapiclient.discovery import build\nfrom googleapiclient.http import MediaIoBaseUpload\n\n# ==============================================================================\n#  HELPER 1: CLEAN SECRETS\n# ==============================================================================\ndef clean_base64(raw_string):\n    """\n    Removes invisible characters (spaces, newlines) from the secrets\n    and fixes the padding so the computer can read them.\n    """\n    cleaned = re.sub(r'[^A-Za-z0-9+/=]', '', raw_string)\n    while len(cleaned) % 4 != 0:\n        cleaned += '='\n    return cleaned\n\n# ==============================================================================\n#  HELPER 2: THE "DATA DIET" (Strict Filter)\n# ==============================================================================\ndef get_clean_summary(raw_sleep, raw_bb):\n    """\n    Takes the massive raw data and extracts ONLY specific numbers.\n    It returns a small dictionary, guaranteeing no 'noise' gets through.\n    """\n    # --- A. SLEEP SUMMARY ---\n    # We use .get() to safely grab data without crashing if something is missing\n    dto = raw_sleep.get('dailySleepDTO', {})\n    scores = dto.get('sleepScores', {})\n    \n    # Convert Total Seconds -> "X hrs Y mins"\n    total_sec = dto.get('sleepTimeSeconds', 0)\n    hrs = int(total_sec // 3600)\n    mins = int((total_sec % 3600) // 60)\n\n    clean_sleep = {\n        "date": dto.get('calendarDate'),\n        "duration": f"{hrs}h {mins}m",\n        "score": scores.get('overall', {}).get('value'),\n        "quality": scores.get('overall', {}).get('qualifierKey'),  # e.g. "GOOD"\n        "deep_sleep_min": int(dto.get('deepSleepSeconds', 0) // 60),\n        "rem_sleep_min": int(dto.get('remSleepSeconds', 0) // 60),\n        "awake_count": dto.get('awakeCount'),\n        "avg_stress": dto.get('avgSleepStress'),\n        "avg_hrv": raw_sleep.get('sleepData', {}).get('avgOvernightHrv'),\n        "resting_hr": dto.get('restingHeartRate')\n    }\n\n    # --- B. BODY BATTERY ---\n    # Garmin returns a list of days; we want the first one (Today)\n    clean_bb = {"status": "No Data"}    \n    if isinstance(raw_bb, list) and len(raw_bb) > 0:\n        day_data = raw_bb[0]\n        # The 'values' array is a graph [time, value]. We grab the LAST one.\n        graph = day_data.get('bodyBatteryValuesArray', [])\n        current_val = graph[-1][1] if graph else "N/A"\n        \n        clean_bb = {\n            "current_level": current_val,\n            "high": day_data.get('charged'),\n            "low": day_data.get('drained')\n        }\n\n    return {\n        "sleep": clean_sleep,\n        "body_battery": clean_bb\n    }\n\n# ==============================================================================\n#   MAIN SCRIPT (Updated with Deep Dive Logic)\n# ==============================================================================\ndef run_sync():\n    print(f"\n{'='*40}\n   🚀 STARTING SYNC (HYBRID MODE)\n{'='*40}\n")\n    \n    try:\n        # --- PHASE 1: LOGIN (Unchanged) ---\n        print("🔐 [1/5] Authenticating...")\n        p1 = os.environ.get("GARMIN_PART1", "")\n        p2 = os.environ.get("GARMIN_PART2", "")\n        p3 = os.environ.get("GARMIN_PART3", "")\n        \n        token = clean_base64(p1 + p2 + p3)\n        if len(token) < 100:\n            print("❌ Error: Secrets are missing.")\n            sys.exit(1)\n\n        garth.client.loads(base64.b64decode(token).decode())\n        client = Garmin()\n        client.garth = garth.client\n        print("   ✅ Logged in.")\n\n        # --- PHASE 2: IDENTIFY USER (Safer) ---\n        print("🕵️ [2/5] Identifying User...")\n        profile = None\n        try:\n            profile = garth.client.connectapi("/userprofile-service/socialProfile")\n            if isinstance(profile, list) and profile:\n                profile = profile[0]\n        except Exception as e:\n            print(f"   ⚠️ Could not fetch profile: {e}")\n            traceback.print_exc()\n            profile = {}\n\n        profile_id = ""\n        if isinstance(profile, dict):\n            profile_id = profile.get("userId") or profile.get("displayName") or ""\n        if profile_id:\n            print(f"   ✅ User identifier: {profile_id}")\n        else:\n            print(f"   ⚠️ No usable userId/displayName found in profile, keys: {list(profile.keys()) if isinstance(profile, dict) else type(profile)}")\n\n        # --- PHASE 3: TIMEZONE (Unchanged) ---\n        CST = timezone(timedelta(hours=-6))\n        now_cst = datetime.now(CST)\n        \n        date_str = now_cst.date().isoformat()       # e.g. 2026-01-17\n        time_str = now_cst.strftime("%H-%M-%S")     # e.g. 16-30-00\n        \n        print(f"\n📅 [3/5] Fetching Data for: {date_str} (CST Time: {time_str})")\n\n        # --- PHASE 4: FETCH DATA ---\n        \n        # A. Clean Data (Your Original Logic)\n        raw_sleep = client.get_sleep_data(date_str)\n        raw_bb = client.get_body_battery(date_str)\n        \n        # B. Deep Dive (Safer: URL-encode, validate, limit)\n        deep_summary = {}\n        try:\n            if profile_id:\n                safe_id = urllib.parse.quote(str(profile_id), safe='')\n                url = f"/usersummary-service/usersummary/daily/{{safe_id}}?calendarDate={{date_str}}"\n                deep_data = garth.client.connectapi(url)\n\n                if isinstance(deep_data, list) and deep_data:\n                    deep_data = deep_data[0]\n\n                if isinstance(deep_data, dict):\n                    # debug info\n                    print(f"   ✅ Deep Dive returned dict with {{len(deep_data)}} keys")\n                    MAX_KEYS = 200\n                    if len(deep_data) > MAX_KEYS:\n                        print(f"   ⚠️ Deep Dive is large ({{len(deep_data)}} keys). Truncating to first {{MAX_KEYS}} keys.")\n                        deep_summary = {k: deep_data[k] for k in list(deep_data.keys())[:MAX_KEYS]}\n                        deep_summary["_truncated"] = True\n                    else:\n                        deep_summary = deep_data\n                else:\n                    # if it's not a dict (maybe an error page or empty), keep empty and log the type\n                    print(f"   ⚠️ Deep Dive returned unexpected type: {{type(deep_data)}}")\n                    deep_summary = {}\n            else:\n                print("   ⚠️ Skipping Deep Dive: no profile id available")\n        except Exception as e:\n            print(f"   ⚠️ Deep Dive Failed: {e}")\n            traceback.print_exc()\n            deep_summary = {}\n\n        # *** FINAL PAYLOAD (Merged) ***\n        final_payload = {\n            "timestamp_cst": f"{date_str}_{time_str}",\n            "metrics": get_clean_summary(raw_sleep, raw_bb), # Your Clean View\n            "deep_dive": deep_summary                        # The Raw Intel\n        }\n        \n        # Show preview in logs\n        print("\n🔍 PREVIEW (Top Level Keys):")\n        print(list(final_payload.keys()))\n        print("   Metrics keys:", list(final_payload["metrics"].keys()))\n        print("   Deep Dive present:", bool(final_payload["deep_dive"]))\n\n        # --- PHASE 5: UPLOAD (Safer & Serializable) ---\n        print("\n☁️  [4/5] Uploading to Drive...")\n        \n        oauth_json = os.environ.get("GDRIVE_OAUTH_JSON")\n        folder_id = os.environ.get("GDRIVE_FOLDER_ID")\n\n        if not oauth_json:\n            print("❌ Missing GDRIVE_OAUTH_JSON environment variable.")\n            sys.exit(1)\n        if not folder_id:\n            print("❌ Missing GDRIVE_FOLDER_ID environment variable.")\n            sys.exit(1)\n\n        # Ensure JSON serializable; sanitize if necessary\n        def sanitize(obj):\n            if obj is None or isinstance(obj, (str, bool, int, float)):\n                return obj\n            if isinstance(obj, dict):\n                return {str(k): sanitize(v) for k, v in obj.items()}\n            if isinstance(obj, list):\n                return [sanitize(v) for v in obj]\n            try:\n                return str(obj)\n            except Exception:\n                return None\n\n        try:\n            json_bytes = json.dumps(final_payload, indent=2).encode()\n        except Exception as e:\n            print("❌ JSON serialization failed; attempting to sanitize deep_dive. Error:", e)\n            traceback.print_exc()\n            sanitized_payload = {\n                "timestamp_cst": final_payload["timestamp_cst"],\n                "metrics": sanitize(final_payload["metrics"]),\n                "deep_dive": sanitize(final_payload["deep_dive"]) if final_payload.get("deep_dive") else {}\n            }\n            try:\n                json_bytes = json.dumps(sanitized_payload, indent=2).encode()\n                final_payload = sanitized_payload\n                print("   ✅ Sanitization succeeded; proceeding with sanitized payload.")\n            except Exception:\n                print("   ❌ Sanitized payload still not JSON-serializable. Falling back to minimal payload.")\n                fallback = {\n                    "timestamp_cst": final_payload["timestamp_cst"],\n                    "metrics": { "sleep": final_payload["metrics"].get("sleep", {}), "body_battery": final_payload["metrics"].get("body_battery", {})},\n                    "deep_dive": {"note": "omitted due to serialization error"}\n                }\n                json_bytes = json.dumps(fallback, indent=2).encode()\n                final_payload = fallback\n\n        # Build Drive service\n        try:\n            creds = Credentials.from_authorized_user_info(json.loads(oauth_json))\n            service = build('drive', 'v3', credentials=creds)\n        except Exception:\n            print("❌ Failed to construct Drive service from GDRIVE_OAUTH_JSON:")\n            traceback.print_exc()\n            sys.exit(1)\n\n        filename = f"health_{{date_str}}_{{time_str}}.json"\n        media = MediaIoBaseUpload(io.BytesIO(json_bytes), mimetype='application/json')\n\n        try:\n            created = service.files().create(body={'name': filename, 'parents': [folder_id]}, media_body=media).execute()\n            print(f"   ✅ Upload Complete! fileId={{created.get('id')}}")\n            print(f"   📄 Saved as: {{filename}}")\n            print(f"\n{'='*40}\n   🎉 SUCCESS \n{'='*40}\n")\n        except Exception:\n            print("❌ Drive upload failed:")\n            traceback.print_exc()\n            sys.exit(1)\n\n    except Exception as e:\n        print(f"\n❌ CRITICAL ERROR: {e}")\n        traceback.print_exc()\n        sys.exit(1)\n